import sys

def search(txt, pat):
    n = len(txt)
    m = len(pat)

    if m == 0 or n == 0 or m > n:
        return []

    # Compute prefix function (pi array) for KMP
    pi = [0] * m
    k = 0
    for q in range(1, m):
        while k > 0 and pat[k] != pat[q]:
            k = pi[k - 1]
        if pat[k] == pat[q]:
            k += 1
        pi[q] = k

    # Search using KMP
    result = []
    q = 0  # number of characters matched
    for i in range(n):
        while q > 0 and pat[q] != txt[i]:
            q = pi[q - 1]
        if pat[q] == txt[i]:
            q += 1
        if q == m:
            # Match found at index i - m + 1 (0-based)
            # Convert to 1-based index
            result.append(i - m + 2)
            q = pi[q - 1]

    return result

def main():
    input_data = sys.stdin.read().splitlines()
    if len(input_data) >= 2:
        txt = input_data[0].strip()
        pat = input_data[1].strip()
        result = search(txt, pat)
        if result:
            print(*(result))
        else:
            print("-1")
    else:
        print("-1")

if __name__ == "__main__":
    main()
